// Ensure ga is initialized before applying options
if (FUZZ_GET_ATTR_INT(ga, "initialized") == 0) {
    sam_global_args_init(ga);
    FUZZ_SET_ATTR_INT(ga, "initialized", 1);
    FUZZ_SET_ATTR_INT(ga, "optcount", 0);
}

// Construct a long-option table consistent with SAM_OPT_GLOBAL_OPTIONS.
// We rely on the project headers to provide struct option and SAM_OPT_* constants.
static const struct option lopt[] = {
    {"input-fmt",           required_argument,  0, SAM_OPT_INPUT_FMT},
    {"input-fmt-option",    required_argument,  0, SAM_OPT_INPUT_FMT_OPTION},
    {"output-fmt",          required_argument,  0, SAM_OPT_OUTPUT_FMT},
    {"output-fmt-option",   required_argument,  0, SAM_OPT_OUTPUT_FMT_OPTION},
    {"reference",           required_argument,  0, SAM_OPT_REFERENCE},
    {"threads",             required_argument,  0, SAM_OPT_NTHREADS},
    {"write-index",         no_argument,        0, SAM_OPT_WRITE_INDEX},
    {"verbosity",           required_argument,  0, SAM_OPT_VERBOSITY},
    {0,0,0,0}
};

// Randomly choose one option to apply
unsigned int idx = (*FUZZ_PARAM(unsigned int)) % 8; // 8 real entries above
int c = lopt[idx].val;

// Prepare optarg according to the selected option's needs
const char *optarg_ptr = NULL;
std::string tmp;
if (lopt[idx].has_arg == required_argument) {
    switch (c) {
        case SAM_OPT_INPUT_FMT:
        case SAM_OPT_OUTPUT_FMT: {
            // format name like "bam", "sam", "cram"; allow arbitrary string
            tmp = FUZZ_PARAM_STR();
            optarg_ptr = tmp.c_str();
            break;
        }
        case SAM_OPT_INPUT_FMT_OPTION:
        case SAM_OPT_OUTPUT_FMT_OPTION: {
            // key=value style; ensure contains '=' to exercise parsing paths
            std::string k = FUZZ_PARAM_STR();
            std::string v = FUZZ_PARAM_STR();
            tmp.reserve(k.size()+1+v.size());
            tmp = k; tmp.push_back('='); tmp += v;
            optarg_ptr = tmp.c_str();
            break;
        }
        case SAM_OPT_REFERENCE: {
            // filename
            optarg_ptr = FUZZ_PARAM_FILENAME();
            break;
        }
        case SAM_OPT_NTHREADS: {
            // small positive integer as string (limit to keep runtime fast)
            int n = (int)(*FUZZ_PARAM(unsigned int) % 17); // 0..16
            static char buf[16];
            // snprintf is safe here; ensure NUL-terminated
            int m = snprintf(buf, sizeof(buf), "%d", n);
            if (m <= 0) { FUZZ_BAIL(); }
            optarg_ptr = buf;
            break;
        }
        case SAM_OPT_VERBOSITY: {
            int v = (int)(*FUZZ_PARAM(unsigned int) % 5); // common 0..4
            static char vbuf[16];
            int m = snprintf(vbuf, sizeof(vbuf), "%d", v);
            if (m <= 0) { FUZZ_BAIL(); }
            optarg_ptr = vbuf;
            break;
        }
        default:
            // Should not happen; defend anyway
            FUZZ_BAIL();
    }
} else {
    // Options with no_argument (e.g., write-index)
    optarg_ptr = NULL;
}

// Apply the chosen option
int ret = parse_sam_global_opt(c, optarg_ptr, lopt, ga);
if (ret < 0) { FUZZ_BAIL(); }

// Track that an option was successfully applied for downstream stubs
FUZZ_SET_ATTR_INT(ga, "optcount", FUZZ_GET_ATTR_INT(ga, "optcount") + 1);
// Return ga as an output so it remains in the pool

// Create a writable FILE* and a correctly-encoded shortopts string.
// According to requirements, the shortopts string must have exactly one character per
// SAM_OPT_GLOBAL_OPTIONS entry in this header (six characters). We'll synthesize six.
const char *path = FUZZ_PARAM_FILENAME();
FILE *fp = fopen(path, "wb+");
if (!fp) { FUZZ_BAIL(); }

// Build a 6-char encoding using '.', '-', or a single visible ASCII letter.
char enc[7];
for (int i = 0; i < 6; i++) {
    unsigned int t = *FUZZ_PARAM(unsigned int);
    char ch;
    switch (t % 4) {
        case 0: ch = '.'; break;           // long-only
        case 1: ch = '-'; break;           // disabled
        case 2: ch = (char)('a' + (t % 26)); break;  // short option letter
        default: ch = (char)('A' + (t % 26)); break; // alternative letter
    }
    enc[i] = ch;
}
enc[6] = '\0';

// Invoke help generator
sam_global_opt_help(fp, enc);

// Close the stream to flush output and avoid descriptor leaks
fclose(fp);

// Initialize structure to defaults before any parsing
sam_global_args_init(ga);
// Record initialization for downstream checks
FUZZ_SET_ATTR_INT(ga, "initialized", 1);
FUZZ_SET_ATTR_INT(ga, "optcount", 0);
// Return ga so it persists in the pool

// Free any dynamic members owned by ga
sam_global_args_free(ga);
// Mark as no longer initialized; caller should re-init before reuse
FUZZ_SET_ATTR_INT(ga, "initialized", 0);
// Keep ga in the pool for potential reinitialization in later stubs

// Use a controlled printf-style format to ensure variadic args match
const char *subcmd = FUZZ_PARAM_STR().c_str();
unsigned int choice = *FUZZ_PARAM(unsigned int) % 3;
if (choice == 0) {
    const char *fmt = "simple error: %s";
    const char *arg1 = FUZZ_PARAM_STR().c_str();
    print_error(subcmd, fmt, arg1);
} else if (choice == 1) {
    const char *fmt = "code=%d name=%s";
    int code = (int)(*FUZZ_PARAM(unsigned int) % 100000);
    const char *name = FUZZ_PARAM_STR().c_str();
    print_error(subcmd, fmt, code, name);
} else {
    const char *fmt = "ptr=%p val=%d";
    void *p = (void*)(uintptr_t)*FUZZ_PARAM(uintptr_t);
    int val = (int)(*FUZZ_PARAM(unsigned int) % 1000);
    print_error(subcmd, fmt, p, val);
}

/* Validation: Selects from a small, type-safe set of format strings with matching arguments to avoid UB while exercising variadic handling. */

// Prepare errno and use controlled, type-safe format strings
errno = (int)(*FUZZ_PARAM(unsigned int) % 256); // bounded errno-like value
const char *subcmd = FUZZ_PARAM_STR().c_str();
unsigned int choice = *FUZZ_PARAM(unsigned int) % 3;
if (choice == 0) {
    const char *fmt = "io error on %s";
    const char *arg1 = FUZZ_PARAM_STR().c_str();
    print_error_errno(subcmd, fmt, arg1);
} else if (choice == 1) {
    const char *fmt = "failed (%d): %s";
    int code = (int)(*FUZZ_PARAM(unsigned int) % 100000);
    const char *desc = FUZZ_PARAM_STR().c_str();
    print_error_errno(subcmd, fmt, code, desc);
} else {
    const char *fmt = "ptr=%p errno=%d";
    void *p = (void*)(uintptr_t)*FUZZ_PARAM(uintptr_t);
    int e = errno;
    print_error_errno(subcmd, fmt, p, e);
}

/* Validation: Ensures errno is set and uses vetted format strings with correct argument lists to safely exercise error + errno reporting. */

// Prepare an aux tag set and a mutable, NUL-terminated argument string
// Initialize the khash set; pass its address so parse_aux_list can (re)use/modify it
auxhash_t h = kh_init(aux_exists);
if (!h) { FUZZ_BAIL(); }

// Generate a candidate comma-separated aux-tag list; ensure it's at least one valid tag
std::string opt_src = FUZZ_PARAM_STR();
if (opt_src.size() < 2) {
    // Use a safe default of common SAM tags (two-char tags, comma-separated)
    opt_src = "NM,MD,AS,RG";
}
// Make it a writable C string for the API taking char *
std::vector<char> opt_buf(opt_src.begin(), opt_src.end());
opt_buf.push_back('\0');
char *optarg = opt_buf.data();

// Message header for diagnostics (doesn't affect parsing semantics)
std::string hdr = FUZZ_PARAM_STR();
const char *msgheader = hdr.c_str();

// Invoke target; it expects a pointer-to-set so it can populate it
int rc = parse_aux_list(&h, optarg, msgheader);
if (rc < 0) {
    // Parsing failed; do not return a partially-populated set
    FUZZ_BAIL();
}

// On success, ensure the set pointer is non-NULL and hand it back to the pool
FUZZ_ASSERT(h != NULL, "parse_aux_list succeeded but returned NULL set");

/* Validation: We pass a valid khash set by address, provide a mutable NUL-terminated list of tags, check rc, and assert a non-NULL result before returning h as an output for reuse. */

// Prepare a valid BED file to satisfy API constraints. FUZZ_PARAM_FILENAME() gives us
// a path to a file containing random data; overwrite it with a minimal valid BED line.
const char *path = FUZZ_PARAM_FILENAME();
{
    // Create a tiny valid BED: chr1 0 1
    FILE *fpw = fopen(path, "wb");
    if (!fpw) { FUZZ_BAIL(); }
    const char *line1 = "chr1\t0\t1\n"; // minimal BED interval
    fwrite(line1, 1, 9, fpw);
    // Optionally append a second region to exercise more paths
    unsigned int add_second = *FUZZ_PARAM(unsigned int) & 1u;
