        fwrite(line2, 1, 10, fpw);
    }
    fclose(fpw);
}
// Call target API
void *h = bed_read(path);
// Enforce non-null handle (treat null as failure to satisfy preconditions)
if (!h) { FUZZ_BAIL(); }
// Track handle provenance and state for downstream stubs
FUZZ_SET_ATTR_STR(h, "bed_kind", "file");
FUZZ_SET_ATTR_INT(h, "unified", 0);
// h is returned as an output (persistent managed by API)

