// Destroy; after this call the handle must not be used, so we do not return it as an output
bed_destroy(_h);
// Drop from pool by not listing as an output

// Validate handle comes from this API
const char *kind = FUZZ_GET_ATTR_STR(_h, "bed_kind");
int is_file = kind && kind[0] && !strcmp(kind, "file");
int is_reg  = kind && kind[0] && !strcmp(kind, "reg");
if (!is_file && !is_reg) { FUZZ_BAIL(); }
// Generate chromosome name: if from a file we created, prefer "chr1" to hit positives
std::string chr_s;
unsigned int prefer_chr1 = *FUZZ_PARAM(unsigned int) & 7u; // 7/8 times choose chr1 for coverage
if (is_file && prefer_chr1) {
    chr_s = "chr1";
} else {
    // Build a simple ASCII chromosome string from fuzz data, fallback to chr1 if empty
    std::string r = FUZZ_PARAM_STR();
    chr_s.reserve(r.size());
    for (char c : r) {
        if ((c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')) chr_s.push_back(c);
        if (chr_s.size() >= 16) break; // keep it short
    }
    if (chr_s.empty()) chr_s = "chr1";
}
const char *chr = chr_s.c_str();
// Generate a valid half-open interval [beg, end)
hts_pos_t beg = (hts_pos_t)(*FUZZ_PARAM(unsigned int) % 1000000u);
hts_pos_t span = (hts_pos_t)((*FUZZ_PARAM(unsigned int) % 1024u) + 1u);
hts_pos_t end = beg + span; // ensure end >= beg and small
// Invoke target; return value semantics are unspecified, so we don't assert on it
(void)bed_overlap(_h, chr, beg, end);
// Persist handle by returning it as an output

// Build a small array of region strings. We'll ensure at least one valid chrom:beg-end
// and optionally add a few more fuzz-derived entries.
const int max_regs = 4;
std::string regs_store[max_regs];
char *regs[max_regs] = {nullptr};
int n = 0;
regs_store[n] = "chr1:1-10"; regs[n] = (char*)regs_store[n].c_str(); n++;
unsigned int extra = *FUZZ_PARAM(unsigned int) % (unsigned int)(max_regs - n + 1);
for (int i = 0; i < (int)extra; i++) {
    // Create simple valid-looking regions from fuzzed numbers
    unsigned int a = *FUZZ_PARAM(unsigned int) % 100000u;
    unsigned int b = a + (unsigned int)(*FUZZ_PARAM(unsigned int) % 1000u + 1u);
    regs_store[n] = "chr1:" + std::to_string(a) + "-" + std::to_string(b);
    regs[n] = (char*)regs_store[n].c_str();
    n++;
}
int first = 0;
int last = n - 1; // inclusive
if (last < first) { FUZZ_BAIL(); }
int op_out = 0;
// Pass NULL to request creation of a new region hash
void *reg_hash = bed_hash_regions(NULL, regs, first, last, &op_out);
if (!reg_hash) { FUZZ_BAIL(); }
// Track provenance and simple metadata for downstream bounds checks
FUZZ_SET_ATTR_STR(reg_hash, "bed_kind", "reg");
FUZZ_SET_ATTR_INT(reg_hash, "unified", 0);
FUZZ_SET_ATTR_INT(reg_hash, "count", n);
FUZZ_SET_ATTR_INT(reg_hash, "op", op_out);
// Return reg_hash as an output (persistent managed by API)

// Ensure this is a region-hash handle created by bed_hash_regions
const char *kind = FUZZ_GET_ATTR_STR(reg_hash, "bed_kind");
if (!(kind && !strcmp(kind, "reg"))) { FUZZ_BAIL(); }
int count = FUZZ_GET_ATTR_INT(reg_hash, "count");
if (count <= 0) { FUZZ_BAIL(); }
int idx = (int)(*FUZZ_PARAM(unsigned int) % (unsigned int)count);
int filter = (int)(*FUZZ_PARAM(unsigned int) & 1u); // 0=ALL,1=FILTERED per docs
// Call target; returned pointer is read-only and owned by the reg_hash. We do not persist it.
(const char*)bed_get(reg_hash, idx, filter);
// Persist reg_hash by returning it as an output

// Validate handle provenance
const char *kind = FUZZ_GET_ATTR_STR(_h, "bed_kind");
int is_file = kind && kind[0] && !strcmp(kind, "file");
int is_reg  = kind && kind[0] && !strcmp(kind, "reg");
if (!is_file && !is_reg) { FUZZ_BAIL(); }
// Invoke target to merge/normalize regions
bed_unify(_h);
// Track that unify has been called
FUZZ_SET_ATTR_INT(_h, "unified", 1);
// Persist handle by returning it as an output

// Enforce preconditions: require an initialized BAM with a valid CIGAR
// Expect prior constructors to have set these attributes when building b
int has_cigar = FUZZ_GET_ATTR_INT(b, "has_valid_cigar");
if (!has_cigar) { /* CIGAR must be valid */ FUZZ_BAIL(); }

// Call target; it mutates b in-place to remove 'B' ops in the CIGAR
// Return code semantics are unspecified; treat non-zero as an allowed path
(void) bam_remove_B(b);

// Since b is mutated and remains owned by the fuzzer pool, return it as an output
// Validation: We ensured b had a valid CIGAR via attribute; we do not assume rc semantics.

// Preconditions: header and b must be non-null and initialized; library may be NULL
// These objects are supplied by the runtime. We optionally consult attributes if present.
int b_ok = FUZZ_GET_ATTR_INT(b, "initialized");
int hdr_ok = FUZZ_GET_ATTR_INT(header, "initialized");
if (!b_ok || !hdr_ok) { FUZZ_BAIL(); }

// Invoke target. The returned pointer, if non-NULL, is owned by header; do not free/modify.
const char *lib = bam_get_library(header, b);

// Track the library name for downstream users (optional, best-effort)
if (lib) {
    FUZZ_SET_ATTR_STR(b, "library_name", lib);
}

// Return persistent inputs to the pool as outputs
// Validation: Ensures both inputs were marked initialized; safely handles NULL return without assuming ownership.

// Require a mapped record with a valid CIGAR and coordinate metadata
int has_cigar = FUZZ_GET_ATTR_INT(b, "has_valid_cigar");
int has_pos   = FUZZ_GET_ATTR_INT(b, "has_valid_pos");
if (!has_cigar || !has_pos) { FUZZ_BAIL(); }

// Compute unclipped start; return value may be any hts_pos_t, including implementation-defined for edge cases
hts_pos_t s = unclipped_start(b);
(void)s; // consumed for coverage only

// Return the input object back to the pool
// Validation: Attribute checks gate invalid states; result is treated as opaque without further assumptions.

// Require a mapped record with a valid CIGAR and coordinate metadata
int has_cigar = FUZZ_GET_ATTR_INT(b, "has_valid_cigar");
int has_pos   = FUZZ_GET_ATTR_INT(b, "has_valid_pos");
if (!has_cigar || !has_pos) { FUZZ_BAIL(); }

// Compute unclipped end; return value is treated as opaque
hts_pos_t e = unclipped_end(b);
(void)e;

// Return the input object back to the pool
// Validation: Attribute checks ensure preconditions; we avoid assumptions about sentinel values.

// Build a syntactically valid CIGAR string with at least one <len><op> pair.
// Use FUZZ_PARAM_STR once and derive numbers/ops from its bytes to avoid FUZZ_PARAM array typing issues.
std::string seed = FUZZ_PARAM_STR();
const char ops_table[] = { 'M','I','D','N','P','X','=', 'S','H' };

std::string cigar_builder;
cigar_builder.reserve(128);

// Parse seed to produce up to 8 operations; ensure each op has length >= 1
unsigned op_count = 0;
size_t i = 0;
while (i < seed.size() && op_count < 8) {
    // Produce a small positive length from a run of bytes
    unsigned len = 0;
    unsigned digits = 0;
    while (i < seed.size() && digits < 3) { // limit to 3 digits for small numbers
        unsigned v = static_cast<unsigned char>(seed[i++]);
        len = (len * 10u) + (v % 10u);
        ++digits;
    }
    if (len == 0) len = 1; // enforce >=1

    // Pick an operation from the allowed table
    unsigned op_idx = 0;
    if (i < seed.size()) {
        op_idx = static_cast<unsigned char>(seed[i++]) % (sizeof(ops_table)/sizeof(ops_table[0]));
    }
    char op = ops_table[op_idx];

    // Append number (base-10) then op
    char numbuf[12];
    unsigned n = 0; unsigned tmp = len;
    do { numbuf[n++] = (char)('0' + (tmp % 10u)); tmp /= 10u; } while (tmp);
    for (int k = (int)n - 1; k >= 0; --k) cigar_builder.push_back(numbuf[k]);
    cigar_builder.push_back(op);
    ++op_count;
}

// Ensure we produced at least one operation
if (op_count == 0) {
    cigar_builder.assign("1M");
}

// Materialize as a mutable, NUL-terminated buffer for API
std::vector<char> cigar_buf(cigar_builder.begin(), cigar_builder.end());
cigar_buf.push_back('\0');

// Choose a non-negative start position in a reasonable range
unsigned int seed_pos = *FUZZ_PARAM(unsigned int);
hts_pos_t op = (hts_pos_t)(seed_pos % 1000000u);

// Precondition checks: cigar must be non-empty and NUL-terminated, op non-negative
if (cigar_buf.size() <= 1) { FUZZ_BAIL(); }

// Call target with constructed inputs
hts_pos_t res = unclipped_other_start(op, cigar_buf.data());
