import random
from typing import List

# Target data type: key=value string
# Used by fuzzer stubs for parse_sam_global_opt when selecting *_FMT_OPTION options.
# We generate valid, interesting key=value strings covering:
# - common HTS format options (e.g., cram/bam/sam options)
# - boolean, integer, and string values
# - multiple value shapes (numbers, on/off, true/false, yes/no, hex-like, paths)
# The fuzzer harness will request a single buffer; we return one NUL-terminated
# key=value string as bytes.

_COMMON_KEYS = [
    # Generic toggles/options likely recognized by htslib/samtools for fmt options
    "level",            # compression level
    "preset",           # preset profiles
    "decode_md",        # flag-like
    "eof",              # write EOF block
    "nthreads",         # threads
    "aux",              # aux handling
    "cigar",            # cigar normalization
    "cigdup",           # cigar duplicate merging
    "cigarx",           # extended cigar
    "pos",              # position fix
    "mqual",            # mapping quality fix
    # CRAM/BAM/SAM specific examples
    "seqs_per_slice",
    "slices_per_container",
    "embed_ref",
    "store_md",
    "store_nm",
    "reference",
    "version",
    "fmt",
    "cram_no_ref",
    "qname",
    "split",
]

_TRUE_VALUES = ["1", "true", "True", "on", "yes", "YES"]
_FALSE_VALUES = ["0", "false", "False", "off", "no", "NO"]
_PRESETS = ["fast", "default", "small", "archive", "cram", "bam", "sam"]
_VERSIONS = ["1.0", "1.3", "1.6", "1.14"]

def _rand_path(rng: random.Random) -> str:
    parts = [rng.choice(["tmp", "var", "data", "home", "ref"]) for _ in range(rng.randint(1, 4))]
    leaf = rng.choice(["ref.fa", "genome.fa", "ref.fasta", "index.fa", "hg19.fa"]) \
        if rng.random() < 0.7 else _rand_ident(rng) + rng.choice([".fa", ".fasta", ""])
    return "/" + "/".join(parts + [leaf])

def _rand_ident(rng: random.Random) -> str:
    alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-."
    n = rng.randint(1, 16)
    return "".join(rng.choice(alphabet) for _ in range(n))

def _rand_int(rng: random.Random, lo: int, hi: int) -> str:
    return str(rng.randint(lo, hi))

def _rand_value_for_key(rng: random.Random, key: str) -> str:
    k = key.lower()
    if k in ("level", "nthreads", "seqs_per_slice", "slices_per_container"):
        # Reasonable numeric ranges
        if k == "level":
            return _rand_int(rng, 0, 12)
        if k == "nthreads":
            return _rand_int(rng, 1, 32)
        return _rand_int(rng, 1, 1000)
    if k in ("decode_md", "eof", "embed_ref", "store_md", "store_nm", "cram_no_ref", "split",
             "aux", "cigar", "cigdup", "cigarx", "pos", "mqual"):
        return rng.choice(_TRUE_VALUES + _FALSE_VALUES)
    if k == "preset":
        return rng.choice(_PRESETS)
    if k == "reference":
        return _rand_path(rng)
    if k == "version":
        return rng.choice(_VERSIONS)
    if k == "fmt":
        return rng.choice(["bam", "sam", "cram"])  # common formats
    if k == "qname":
        return _rand_ident(rng)
    # Fallback: random identifier or int
    return rng.choice([_rand_ident(rng), _rand_int(rng, 0, 100)])

def _rand_key(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return rng.choice(_COMMON_KEYS)
    # Occasionally produce arbitrary but sane identifiers
    return _rand_ident(rng)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a key and construct a valid key=value with no spaces around '='
    key = _rand_key(rng)
    val = _rand_value_for_key(rng, key)

    # Occasionally quote stringy values to exercise parsers that accept quotes
    if isinstance(val, str) and any(ch in val for ch in ['/', '.', '-', ':']) and rng.random() < 0.3:
        # Use simple quotes without spaces
        if '"' not in val:
            val = f'"{val}"'
        elif "'" not in val:
            val = f"'{val}'"
        # else leave as-is to avoid escaping complexity

    s = f"{key}={val}"

    # Ensure NUL-terminated when interpreted as C-string, but do not include embedded NULs
    data = s.encode('utf-8') + b"\x00"

    # Keep under 4096 bytes by construction; assert for safety
    if len(data) > 4096:
        data = data[:4095] + b"\x00"

    return data
